import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    label = int(ctx.index) % 2
    inputs = torch.cat((torch.tensor([float(label)]), torch.randn(6, generator=ctx.rng.torch)))
    return {"inputs": synth.Tensor(inputs)}
class FixMatchModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=6, out_features=6)
    def forward(self, inputs):
        if inputs.shape[-1] < 7:
            padding = inputs.new_zeros((inputs.shape[0], 7 - inputs.shape[-1]))
            inputs = torch.cat((inputs, padding), dim=-1)
        outputs = self.network(inputs[:, 1:])
        return {"logits": outputs[:, :2], "weak_logits": outputs[:, 2:4], "strong_logits": outputs[:, 4:6], "targets": inputs[:, 0].long()}
ds = synth.Spec("fixmatch-data", generator=samples, size=16, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = ds.for_recipe("structured-objective", split="train")
trainer = Trainer(FixMatchModel(), train, recipe="structured-objective", recipe_config={"loss": "fixmatch", "loss_kwargs": {"threshold": 0.95, "unlabeled_weight": 1.0}, "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"output": "targets"}, "weak_logits": {"output": "weak_logits"}, "strong_logits": {"output": "strong_logits"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
